    if (!x) return Response.json({ error: 'Konten tidak ditemukan' }, { status: 404 });
    // idea_id: id satu ide, "*" = semua ide konten ini, kosong = tanpa ide khusus
    const ideas = !b.idea_id ? [] : ((await env.DB.prepare(`SELECT id, text FROM ci_ideas WHERE content_id = ?${b.idea_id === '*' ? '' : ' AND id = ?'} ORDER BY at`).bind(...(b.idea_id === '*' ? [x.id] : [x.id, String(b.idea_id)])).all()).results || []);
    const extra = String(b.extra || '').trim().slice(0, 500);
    let c = null, model = '', why = '';
    try {
      for (let retry = false, n = 0; n < 2 && !c; n++) {
        const { system, user } = conceptPrompt(env, x, ideas, extra, retry);
        const r = await ai(env, system, user, 2200); model = r.model;
        const p = parseConcept(r.text);
        if (!p) { why = 'Jawaban AI tidak lengkap.'; continue; }
        if (overlap(x.caption, [p.hook, p.caption, ...p.alur.map((a) => a.isi)].join(' ')) > 0.2) { why = 'Konsep terlalu mirip dengan konten kompetitor.'; retry = true; continue; }
        c = p;
      }
    } catch (e) { return Response.json({ error: e instanceof AiError ? e.message : 'AI gagal: ' + (e.message || e) }, { status: 502 }); }
    if (!c) return Response.json({ error: why + ' Coba buat lagi.' }, { status: 502 });
    const row = { id: crypto.randomUUID(), content_id: x.id, idea_id: b.idea_id ? String(b.idea_id).slice(0, 40) : null, body: JSON.stringify(c), model, by_name: me.name, by_email: me.email, at: ciNow() };
    const k = Object.keys(row);
    await env.DB.prepare(`INSERT INTO ci_concepts (${k.join(',')}) VALUES (${k.map(() => '?').join(',')})`).bind(...k.map((y) => row[y])).run();
